import { createHash } from 'node:crypto';

// Kept byte-for-byte identical to the reviewed decoder-valid JPEG policy fixture.
const JPEG_BASE64 = '';
const JPEG_BYTES = Uint8Array.from(Buffer.from(JPEG_BASE64, 'base64'));
const JPEG_SHA256 = createHash('sha256').update(JPEG_BYTES).digest('hex');

export function deterministicJpegFixture(): Readonly<{
  bytes: Uint8Array;
  sha256: string;
  width: number;
  height: number;
}> {
  return { bytes: JPEG_BYTES.slice(), sha256: JPEG_SHA256, width: 1, height: 1 };
}
